 private void applyAwake(){if(params==null||window==null)return;if(getSharedPreferences("settings",0).getBoolean("stay_awake",false))params.flags|=WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON;else params.flags&=~WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON;try{wm.updateViewLayout(window,params);}catch(Exception ignored){stopSelf();}}
